function parseNdjson(text){
  var src = String(text===undefined?'':text);
  var lines = src.split(/\r?\n/);
  var rows=[], errors=[], blank=0;
  for(var i=0;i<lines.length;i++){
    var raw=lines[i];
    if(!raw.trim()){ blank++; continue; }
    try {
      rows.push({line:i+1, value: JSON.parse(raw)});
    } catch(e){
      errors.push({line:i+1, message: String(e.message||e), preview: raw.length>80 ? raw.slice(0,80)+'…' : raw});
    }
  }
  return {rows:rows, errors:errors, blank:blank, totalLines:lines.length, ok: errors.length===0};
}
function stringifyNdjson(arr, pretty){
  if(!Array.isArray(arr)) return {text:'', count:0, error:'输入必须是数组'};
  var out=[];
  for(var i=0;i<arr.length;i++) out.push(JSON.stringify(arr[i]));
  return {text: out.join('\n'), count: out.length, error:null};
}
function fromJsonArray(text){
  var v;
  try { v = JSON.parse(String(text||'')); } catch(e){ return {text:'', count:0, error:'JSON 解析失败: '+e.message}; }
  if(!Array.isArray(v)){
    if(v && typeof v==='object') return stringifyNdjson([v]);
    return {text:'', count:0, error:'顶层不是数组，无法逐行展开'};
  }
  return stringifyNdjson(v);
}
function toJsonArray(text, pretty){
  var p=parseNdjson(text);
  var vals=[];
  for(var i=0;i<p.rows.length;i++) vals.push(p.rows[i].value);
  return {text: pretty ? JSON.stringify(vals, null, 2) : JSON.stringify(vals), count: vals.length, errors: p.errors};
}
function typeOf(v){
  if(v===null) return 'null';
  if(Array.isArray(v)) return 'array';
  var t=typeof v;
  if(t==='number') return Number.isInteger(v) ? 'integer' : 'number';
  return t;
}
function flattenObject(obj, prefix, out, depth){
  out = out || {};
  depth = depth===undefined ? 0 : depth;
  prefix = prefix || '';
  if(depth>8) { out[prefix||'$']=obj; return out; }
  if(obj===null || typeof obj!=='object' || Array.isArray(obj)){
    out[prefix||'$']=obj;
    return out;
  }
  var keys=Object.keys(obj);
  if(!keys.length){ out[prefix||'$']={}; return out; }
  for(var i=0;i<keys.length;i++){
    var k=keys[i], key = prefix ? prefix+'.'+k : k, v=obj[k];
    if(v && typeof v==='object' && !Array.isArray(v)) flattenObject(v, key, out, depth+1);
    else out[key]=v;
  }
  return out;
}
function profileSchema(text){
  var p=parseNdjson(text);
  var fields={}, order=[], total=p.rows.length;
  for(var i=0;i<p.rows.length;i++){
    var flat=flattenObject(p.rows[i].value);
    for(var k in flat){
      if(!flat.hasOwnProperty(k)) continue;
      if(!fields[k]){ fields[k]={name:k, count:0, types:{}, nulls:0, samples:[]}; order.push(k); }
      var f=fields[k];
      f.count++;
      var t=typeOf(flat[k]);
      if(t==='null') f.nulls++;
      f.types[t]=(f.types[t]||0)+1;
      if(f.samples.length<3 && t!=='null') f.samples.push(flat[k]);
    }
  }
  var list=[];
  for(var j=0;j<order.length;j++){
    var g=fields[order[j]];
    var tk=Object.keys(g.types);
    tk.sort(function(a,b){ return g.types[b]-g.types[a]; });
    list.push({
      name:g.name, count:g.count, presence: total? Math.round(g.count/total*100) : 0,
      types:tk, primaryType: tk[0]||'unknown', mixed: tk.filter(function(x){return x!=='null';}).length>1,
      nulls:g.nulls, samples:g.samples
    });
  }
  return {fields:list, records:total, errors:p.errors, fieldCount:list.length};
}
function validateShape(text){
  var prof=profileSchema(text), issues=[];
  for(var i=0;i<prof.fields.length;i++){
    var f=prof.fields[i];
    if(f.presence<100 && prof.records>1) issues.push({level:'warn', field:f.name, msg:'字段仅在 '+f.presence+'% 的记录中出现'});
    if(f.mixed) issues.push({level:'error', field:f.name, msg:'类型不一致: '+f.types.join(' / ')});
  }
  for(var j=0;j<prof.errors.length;j++) issues.push({level:'error', field:'第 '+prof.errors[j].line+' 行', msg:prof.errors[j].message});
  var errors=0, warnings=0;
  for(var k=0;k<issues.length;k++){ if(issues[k].level==='error') errors++; else warnings++; }
  return {issues:issues, errors:errors, warnings:warnings, ok: errors===0, records:prof.records, fieldCount:prof.fieldCount};
}
function csvEscape(v){
  if(v===null || v===undefined) return '';
  var s = (typeof v==='object') ? JSON.stringify(v) : String(v);
  if(/[",\n\r]/.test(s)) return '"'+s.replace(/"/g,'""')+'"';
  return s;
}
function toCsv(text, delimiter){
  var d = delimiter || ',';
  var p=parseNdjson(text);
  if(!p.rows.length) return {text:'', rows:0, columns:[], error:'无有效记录'};
  var cols=[], seen={};
  var flats=[];
  for(var i=0;i<p.rows.length;i++){
    var f=flattenObject(p.rows[i].value);
    flats.push(f);
    for(var k in f){ if(f.hasOwnProperty(k) && !seen[k]){ seen[k]=1; cols.push(k); } }
  }
  var out=[cols.map(csvEscape).join(d)];
  for(var j=0;j<flats.length;j++){
    var row=[];
    for(var c=0;c<cols.length;c++) row.push(csvEscape(flats[j][cols[c]]));
    out.push(row.join(d));
  }
  return {text: out.join('\n'), rows: flats.length, columns: cols, error:null};
}
function filterLines(text, expr){
  var p=parseNdjson(text);
  var q=String(expr||'').trim();
  if(!q) return {text: p.rows.map(function(r){return JSON.stringify(r.value);}).join('\n'), matched:p.rows.length, total:p.rows.length, error:null};
  var m = q.match(/^([A-Za-z0-9_.$[\]]+)\s*(==|!=|>=|<=|>|<|~)\s*(.+)$/);
  if(!m) return {text:'', matched:0, total:p.rows.length, error:'表达式格式: field op value（op 为 == != > < >= <= ~）'};
  var field=m[1], op=m[2], rhs=m[3].trim().replace(/^["']|["']$/g,'');
  var num=parseFloat(rhs), isNum=!isNaN(num) && /^-?\d+(\.\d+)?$/.test(rhs);
  var kept=[];
  for(var i=0;i<p.rows.length;i++){
    var flat=flattenObject(p.rows[i].value);
    var v=flat[field];
    var pass=false;
    if(op==='~') pass = v!==undefined && String(v).indexOf(rhs)>-1;
    else if(op==='==') pass = String(v)===rhs || (isNum && v===num);
    else if(op==='!=') pass = !(String(v)===rhs || (isNum && v===num));
    else {
      var lv = typeof v==='number' ? v : parseFloat(v);
      if(isNaN(lv) || !isNum) pass=false;
      else if(op==='>') pass = lv>num;
      else if(op==='<') pass = lv<num;
      else if(op==='>=') pass = lv>=num;
      else if(op==='<=') pass = lv<=num;
    }
    if(pass) kept.push(JSON.stringify(p.rows[i].value));
  }
  return {text: kept.join('\n'), matched: kept.length, total: p.rows.length, error:null};
}
function stats(text){
  var p=parseNdjson(text);
  var bytes=0, maxLine=0, types={};
  var src=String(text||'').split(/\r?\n/);
  for(var i=0;i<src.length;i++){
    bytes += src[i].length + 1;
    if(src[i].length>maxLine) maxLine=src[i].length;
  }
  for(var j=0;j<p.rows.length;j++){
    var t=typeOf(p.rows[j].value);
    types[t]=(types[t]||0)+1;
  }
  return {
    records:p.rows.length, invalid:p.errors.length, blank:p.blank,
    bytes: bytes>0 ? bytes-1 : 0,
    avgBytes: p.rows.length ? Math.round((bytes-1)/p.rows.length) : 0,
    maxLineLength:maxLine, valueTypes:types
  };
}
if (typeof module !== 'undefined' && module.exports) { module.exports = { parseNdjson:parseNdjson, stringifyNdjson:stringifyNdjson, fromJsonArray:fromJsonArray, toJsonArray:toJsonArray, typeOf:typeOf, flattenObject:flattenObject, profileSchema:profileSchema, validateShape:validateShape, csvEscape:csvEscape, toCsv:toCsv, filterLines:filterLines, stats:stats }; }
if (typeof window !== 'undefined') { window.NdjsonForgePure = { parseNdjson:parseNdjson, stringifyNdjson:stringifyNdjson, fromJsonArray:fromJsonArray, toJsonArray:toJsonArray, typeOf:typeOf, flattenObject:flattenObject, profileSchema:profileSchema, validateShape:validateShape, csvEscape:csvEscape, toCsv:toCsv, filterLines:filterLines, stats:stats }; }
